            ctx.beginPath();
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
            // Bus and docking collar
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.rect(-9, -6, 18, 12); ctx.fill(); ctx.stroke();
            ctx.fillRect(9, -3.5, 4, 7); ctx.strokeRect(9, -3.5, 4, 7);
            ctx.beginPath(); ctx.arc(-2, 0, 2.3, 0, Math.PI * 2);
            ctx.fillStyle = color; ctx.fill();
            ctx.restore();
