            var goal = project(panel, 0, 0);
            ctx.beginPath(); ctx.arc(goal.x, goal.y, GOAL_RADIUS * panel.scale, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(227,95,111,.07)'; ctx.fill();
            ctx.setLineDash([4, 4]);
            ctx.strokeStyle = 'rgba(227,95,111,.5)'; ctx.stroke();
            ctx.setLineDash([]);
            drawSpacecraft(goal.x + 26 * panel.size, goal.y, Math.PI, colors.faint, panel.size, colors, { target: true });

            // Trajectory so far, start marker and current pose
            var count = Math.max(2, Math.floor(progress * (points.length - 1)) + 1);
            ctx.beginPath();
            for (var i = 0; i < count; i++) {
                var p = project(panel, points[i][0], points[i][1]);
                if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
            }
            ctx.strokeStyle = color; ctx.globalAlpha = 0.85; ctx.lineWidth = 2;
            ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.stroke();
            ctx.globalAlpha = 1;
